sp_CriarEndereco	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarEndereco`(\n\n    IN tipoEndereco INT,\n\n    IN logradouro   VARCHAR(255),\n\n    IN numero       VARCHAR(20),\n\n    IN complemento  VARCHAR(100),\n\n    IN bairro       VARCHAR(100),\n\n    IN cidade       VARCHAR(100),\n\n    IN estado       CHAR(2),\n\n    IN pais         VARCHAR(50),\n\n    IN cep          CHAR(8),\n\n    IN fAtivo       TINYINT(1)\n\n)\nBEGIN\n\n    INSERT INTO Endereco (tipoEndereco, Logradouro, Numero, Complemento, Bairro, Cidade, Estado, Pais, CEP, fAtivo)\n\n    VALUES (tipoEndereco, logradouro, numero, complemento, bairro, cidade, estado, pais, cep, fAtivo);\n\n\n\n    SELECT LAST_INSERT_ID() AS idEndereco;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
